template <typename UnionPtrType>
AccessibilityWindowKeyPtr AccessibilityWindowKey::Clone() const {
  switch (tag_) {
    case Tag::kWindowId:
      return NewWindowId(
          mojo::Clone(data_.window_id));
    case Tag::kTaskId:
      return NewTaskId(
          mojo::Clone(data_.task_id));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, AccessibilityWindowKey>::value>::type*>
bool AccessibilityWindowKey::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kWindowId:
      return mojo::Equals(data_.window_id, other.data_.window_id);
    case Tag::kTaskId:
      return mojo::Equals(data_.task_id, other.data_.task_id);
  }

  return false;
}
